arguments.command:
cd /tmp/opencode && python3 -c "
import json
b=json.load(open('before.json')); a=json.load(open('after.json'))
cols=('cat','subcat','merch','party','party2')
uniq={}
for k in b:
    if b[k]==a[k]: continue
    acct,desc,rem,typ,amt=k.split('|')
    ch=tuple((c,p,q) for c,p,q in zip(cols,b[k],a[k]) if p!=q)
    uniq.setdefault((ch,typ),set()).add((desc,rem,amt))
print('=== CATEGORY CHANGES ===')
for (ch,typ),rows in sorted(uniq.items(), key=lambda x:str(x)):
    if ch[0][0]!='cat': continue
    print(f'{typ}: '+', '.join(f'{c} {p!r}->{q!r}' for c,p,q in ch))
    for d,r,am in sorted(rows)[:6]: print(f'     amt={am:>7} rem={r!r:>16}  {d!r}')
    if len(rows)>6: print(f'     ... {len(rows)-6} more descriptions')
print()
print('=== PARTYNAME CHANGES ===')
for (ch,typ),rows in sorted(uniq.items(), key=lambda x:str(x)):
    if ch[0][0]=='cat': continue
    print(f'{typ}: '+', '.join(f'{c} {p!r}->{q!r}' for c,p,q in ch))
    for d,r,am in sorted(rows): print(f'     amt={am:>7} rem={r!r:>16}  {d!r}')
"

